Co-SMOS v1.1.7 — Task Explorer: sort + filter by author + search

CONTEXT:
- Repo: Urania-order/jules
- File: frontend/index.html
- v1.1.6 (just applied) populated task.created_at and task.proposed_by
  in state.json → API /api/tasks now returns these fields.

GOAL:

1. Add shared JS helpers in frontend/index.html:

   function sortTasksByCreatedAt(tasks, desc = true) {
     const key = (t) => t.created_at || '';
     return [...tasks].sort((a, b) => {
       const ka = key(a), kb = key(b);
       if (!ka && !kb) return 0;
       if (!ka) return 1;
       if (!kb) return -1;
       return desc ? kb.localeCompare(ka) : ka.localeCompare(kb);
     });
   }

   function filterTasksByAuthor(tasks, author) {
     if (!author || author === 'all') return tasks;
     return tasks.filter(t => (t.proposed_by || 'unknown') === author);
   }

   function searchTasks(tasks, q) {
     if (!q) return tasks;
     const needle = q.toLowerCase();
     return tasks.filter(t => {
       const hay = [t.id, t.title, t.request, t.proposed_by]
         .filter(Boolean).join(' ').toLowerCase();
       return hay.includes(needle);
     });
   }

   function applyTaskFilters(tasks) {
     const author = document.getElementById('task-filter-author')?.value || 'all';
     const q = document.getElementById('task-filter-search')?.value || '';
     const order = document.getElementById('task-sort-order')?.value || 'desc';
     let out = tasks;
     out = filterTasksByAuthor(out, author);
     out = searchTasks(out, q);
     out = sortTasksByCreatedAt(out, order === 'desc');
     return out;
   }

2. Apply in Queue (renderQueue):
   - Wrap currentTasks with applyTaskFilters before rendering
3. Apply in Commands (renderSequence):
   - Same applyTaskFilters
4. Apply in Batch (renderBatchTasks):
   - Same applyTaskFilters

5. Add UI controls in Queue header:
   - <select id="task-filter-author">
       <option value="all">All authors</option>
       <option value="operator">🧑 operator</option>
       <option value="queue">⚙ queue</option>
       <option value="consultant">✨ consultant</option>
       <option value="unknown">? unknown</option>
     </select>
   - <select id="task-sort-order">
       <option value="desc">↓ Newest</option>
       <option value="asc">↑ Oldest</option>
     </select>
   - <input id="task-filter-search" type="text"
            placeholder="Search id / title / request / author">

6. Persist in localStorage:
   - cosmos_task_author_filter
   - cosmos_task_sort_order
   - cosmos_task_search_q

7. Show author badge on task cards:
   - 🧑 operator
   - ⚙ queue
   - ✨ consultant
   - ? unknown

